Drafts for round 2:
T34 balanced brackets: stack, pairs={'(':')','[':']','{':'}'}; for ch in s: if ch in pairs: push; elif ch in ')]}': if not stack or stack.pop()!=matching -> False. return not stack.
def solve(s):
    st=[]; pair={')':'(',']':'[','}':'{'}
    for ch in s:
        if ch in '([{': st.append(ch)
        elif ch in ')]}':
            if not st or st.pop()!=pair[ch]: return False
    return not st
T32 roman: vals {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}; total=sum(v if v>=next else -v).
def solve(s):
    v={'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    t=0
    for i,c in enumerate(s):
        if i+1<len(s) and v[c]<v[s[i+1]]: t-=v[c]
        else: t+=v[c]
    return t
